<template><div class="modal-backdrop" @mousedown.self="$emit('close')"><form class="modal invite-dialog" @submit.prevent="$emit('send',{...form})"><div class="modal-head"><div><h2>Convidar para o workspace</h2><p>Compartilhe <strong>{{workspace}}</strong> com sua equipe.</p></div><button type="button" @click="$emit('close')"><X/></button></div><label>E-mail<input v-model="form.email" type="email" placeholder="nome@email.com" required/></label><div class="modal-fields"><label>Função no workspace<input v-model="form.job"/></label><label>Permissão<select v-model="form.role"><option>Membro</option><option>Administrador</option></select></label></div><button class="primary-btn invite-send"><Send/>Gerar convite</button><section class="invite-link-section"><div><strong>Link de convite</strong><small>Copie e compartilhe; o e-mail não é enviado automaticamente.</small></div><div class="invite-link"><span>{{link||'Gere um convite para obter o link.'}}</span><button type="button" :disabled="!link" @click="copy"><Copy/>{{copied?'✓ Link copiado':'Copiar link'}}</button></div><div class="invite-link-actions"><label><input :checked="Boolean(link)" type="checkbox" :disabled="!link" @change="$emit('revoke')"/>Permitir entrada através deste link</label><button type="button" :disabled="!link" @click="$emit('regenerate')"><RefreshCw/>Regenerar link</button></div><div v-for="item in invitations.filter(item=>item.status==='PENDING')" :key="item.id" class="invite-link-actions"><span>{{item.email}} · {{item.role}}</span><button type="button" @click="$emit('revoke-id',item.id)">Revogar</button></div></section></form></div></template>
<script setup lang="ts">import{reactive,ref}from"vue";import{Copy,RefreshCw,Send,X}from"lucide-vue-next";import type{InvitationRecord}from"../stores/workspaces";const props=defineProps<{workspace:string;link?:string;invitations:InvitationRecord[]}>();defineEmits(["close","send","regenerate","revoke","revoke-id"]);const form=reactive({email:"",job:"",role:"Membro"}),copied=ref(false);async function copy(){if(!props.link)return;await navigator.clipboard.writeText(props.link);copied.value=true}</script>
